28	/** Factory methods for creating {@link Call} instances which immediately respond or fail. */
29	public final class Calls {
30	  /**
31	   * Invokes {@code callable} once for the returned {@link Call} and once for each instance that is
32	   * obtained from {@linkplain Call#clone() cloning} the returned {@link Call}.
33	   */
34	  public static <T> Call<T> defer(Callable<Call<T>> callable) {
35	    return new DeferredCall<>(callable);
36	  }
37	
38	  public static <T> Call<T> response(@Nullable T successValue) {
39	    return new FakeCall<>(Response.success(successValue), null);
40	  }
41	
42	  public static <T> Call<T> response(Response<T> response) {
43	    return new FakeCall<>(response, null);
44	  }
45	
46	  /** Creates a failed {@link Call} from {@code failure}. */
47	  public static <T> Call<T> failure(IOException failure) {
48	    // TODO delete this overload in Retrofit 3.0.
49	    return new FakeCall<>(null, failure);
50	  }
51	
52	  /**
53	   * Creates a failed {@link Call} from {@code failure}.
54	   *
55	   * <p>Note: When invoking {@link Call#execute() execute()} on the returned {@link Call}, if {@code
56	   * failure} is a {@link RuntimeException}, {@link Error}, or {@link IOException} subtype it is
57	   * thrown directly. Otherwise it is "sneaky thrown" despite not being declared.
58	   */
59	  public static <T> Call<T> failure(Throwable failure) {
60	    return new FakeCall<>(null, failure);
61	  }
62	
63	  private Calls() {
64	    throw new AssertionError("No instances.");
65	  }
66	
67	  static final class FakeCall<T> implements Call<T> {
68	    private final Response<T> response;
69	    private final Throwable error;
70	    private final AtomicBoolean canceled = new AtomicBoolean();
71	    private final AtomicBoolean executed = new AtomicBoolean();
72	
73	    FakeCall(@Nullable Response<T> response, @Nullable Throwable error) {
74	      if ((response == null) == (error == null)) {
75	        throw new AssertionError("Only one of response or error can be set.");
76	      }
77	      this.response = response;
78	      this.error = error;
79	    }
80	
81	    @Override
82	    public Response<T> execute() throws IOException {
83	      if (!executed.compareAndSet(false, true)) {
84	        throw new IllegalStateException("Already executed");
85	      }
86	      if (canceled.get()) {
87	        throw new IOException("canceled");
88	      }
89	      if (response != null) {
90	        return response;
91	      }
92	      throw FakeCall.<Error>sneakyThrow(error);
93	    }
94	
95	    // Intentionally abusing this feature.
96	    @SuppressWarnings({"unchecked", "TypeParameterUnusedInFormals"})
97	    private static <T extends Throwable> T sneakyThrow(Throwable t) throws T {
98	      throw (T) t;
99	    }
100	
101	    @SuppressWarnings("ConstantConditions") // Guarding public API nullability.
102	    @Override
103	    public void enqueue(Callback<T> callback) {
104	      if (callback == null) {
105	        throw new NullPointerException("callback == null");
106	      }
107	      if (!executed.compareAndSet(false, true)) {
108	        throw new IllegalStateException("Already executed");
109	      }
110	      if (canceled.get()) {
111	        callback.onFailure(this, new IOException("canceled"));
112	      } else if (response != null) {
113	        callback.onResponse(this, response);
114	      } else {
115	        callback.onFailure(this, error);
116	      }
117	    }
118	
119	    @Override
120	    public boolean isExecuted() {
121	      return executed.get();
122	    }
123	
124	    @Override
125	    public void cancel() {
126	      canceled.set(true);
127	    }
128	
129	    @Override
130	    public boolean isCanceled() {
131	      return canceled.get();
132	    }
133	
134	    @Override
135	    public Call<T> clone() {
136	      return new FakeCall<>(response, error);
137	    }
138	
139	    @Override
140	    public Request request() {
141	      if (response != null) {
142	        return response.raw().request();
143	      }
144	      return new Request.Builder().url("http://localhost").build();
145	    }
146	
147	    @Override
148	    public Timeout timeout() {
149	      return Timeout.NONE;
150	    }
151	  }
152	
153	  static final class DeferredCall<T> implements Call<T> {
154	    private final Callable<Call<T>> callable;
155	    private @Nullable Call<T> delegate;
156	
157	    DeferredCall(Callable<Call<T>> callable) {
158	      this.callable = callable;
159	    }
160	
161	    private synchronized Call<T> getDelegate() {
162	      Call<T> delegate = this.delegate;
163	      if (delegate == null) {
164	        try {
165	          delegate = callable.call();
166	        } catch (Exception e) {
167	          delegate = failure(e);
168	        }
169	        this.delegate = delegate;
170	      }
171	      return delegate;
172	    }
173	
174	    @Override
175	    public Response<T> execute() throws IOException {
176	      return getDelegate().execute();
177	    }
178	
179	    @Override
180	    public void enqueue(Callback<T> callback) {
181	      getDelegate().enqueue(callback);
182	    }
183	
