    call.enqueue(
        new Callback<String>() {
          @Override
          public void onResponse(Call<String> call, Response<String> response) {
            latch.countDown();
          }

          @Override
          public void onFailure(Call<String> call, Throwable t) {
            failureRef.set(t);
            latch.countDown();
          }
        });

    // TODO we shouldn't need to sleep
    Thread.sleep(100); // Ensure the task has started.
    call.cancel();

    assertTrue(latch.await(1, SECONDS));

    Throwable failure = failureRef.get();
    // Exact instance check as opposed to isInstanceOf's subtype checking.
    assertThat(failure.getClass()).isEqualTo(IOException.class);
    assertThat(failure).hasMessageThat().isEqualTo("canceled");
  }

