    class Example {
      @GET("/foo/bar/{taco}/or/{burrito}")
      Call<ResponseBody> method(@Path("taco") String taco, @Path("burrito") String burrito) {
        return null;
      }
    }
    Request request = buildRequest(Example.class, "one", "two");
    assertThat(request.url().toString()).isEqualTo("http://example.com/foo/bar/one/or/two");
  }

