    // fail to build.
    class Example {
      @GET("/{taco}/{tAco}/{taCo}")
      Call<ResponseBody> method(
          @Path("taco") String a, @Path("tAco") String b, @Path("taCo") String c) {
        return null;
      }
    }
    Request request = buildRequest(Example.class, "1", "2", "3");
    assertThat(request.url().toString()).isEqualTo("http://example.com/1/2/3");
  }

