  public void parameterNamesAllowLettersDigitsHyphensAndUnderscores() {
    class Example {
      @GET("/{taco-shell}/{taco_shell}/{sha256}")
      Call<ResponseBody> method(
          @Path("taco-shell") String a, @Path("taco_shell") String b, @Path("sha256") String c) {
        return null;
      }
    }
    Request request = buildRequest(Example.class, "1", "2", "3");
    assertThat(request.url().toString()).isEqualTo("http://example.com/1/2/3");
